#include <stdio.h>
#include <stdlib.h>

#define MAXN 100005
#define LOGN 20

int head[MAXN], to[MAXN], nxt[MAXN], edge_cnt = 0;

void add_edge(int u, int v) {
    edge_cnt++;
    to[edge_cnt] = v;
    nxt[edge_cnt] = head[u];
    head[u] = edge_cnt;
}

int up[LOGN][MAXN];
int depth[MAXN];
int tin[MAXN], tout[MAXN], timer = 0;

void dfs(int u, int p, int d) {
    depth[u] = d;
    up[0][u] = p;
    for (int i = 1; i < LOGN; i++) {
        up[i][u] = up[i - 1][up[i - 1][u]];
    }

    timer++;
    tin[u] = timer;

    for (int e = head[u]; e; e = nxt[e]) {
        int v = to[e];
        dfs(v, u, d + 1);
    }

    tout[u] = timer;
}

int get_kth_ancestor(int u, int k) {
    for (int i = LOGN - 1; i >= 0; i--) {
        if ((k >> i) & 1) {
            u = up[i][u];
        }
    }
    return u;
}

int lazy[4 * MAXN];

void push(int node) {
    if (lazy[node] != 0) {
        lazy[2 * node] = lazy[node];
        lazy[2 * node + 1] = lazy[node];
        lazy[node] = 0;
    }
}

void update(int node, int l, int r, int ql, int qr, int val) {
    if (ql > r || qr < l) return;
    if (ql <= l && r <= qr) {
        lazy[node] = val;
        return;
    }
    push(node);
    int mid = (l + r) / 2;
    update(2 * node, l, mid, ql, qr, val);
    update(2 * node + 1, mid + 1, r, ql, qr, val);
}

int query(int node, int l, int r, int pos) {
    if (l == r) {
        return lazy[node];
    }
    push(node);
    int mid = (l + r) / 2;
    if (pos <= mid) {
        return query(2 * node, l, mid, pos);
    } else {
        return query(2 * node + 1, mid + 1, r, pos);
    }
}

static inline int read_int() {
    int c = getchar();
    while (c <= ' ' && c != EOF) c = getchar();
    if (c == EOF) return 0;
    int res = 0;
    while (c >= '0' && c <= '9') {
        res = res * 10 + (c - '0');
        c = getchar();
    }
    return res;
}

static inline void print_int(int x) {
    char buf[12];
    int len = 0;
    if (x == 0) {
        putchar('0');
        putchar('\n');
        return;
    }
    while (x > 0) {
        buf[len++] = (x % 10) + '0';
        x /= 10;
    }
    while (len > 0) {
        putchar(buf[--len]);
    }
    putchar('\n');
}

int main() {
    int N = read_int();
    for (int i = 2; i <= N; i++) {
        int p = read_int();
        add_edge(p, i);
    }

    dfs(1, 1, 0);

    int Q = read_int();
    for (int q = 0; q < Q; q++) {
        int type = read_int();
        if (type == 1) {
            int v = read_int();
            int k = read_int();

            int A = query(1, 1, N, tin[v]);
            if (A == 0) {
                print_int(get_kth_ancestor(v, k));
            } else {
                if (k == 1) {
                    print_int(A);
                } else {
                    print_int(get_kth_ancestor(A, k - 1));
                }
            }
        } else {
            int v = read_int();
            int anc_mark = query(1, 1, N, tin[v]);
            if (anc_mark == 0) {
                if (tin[v] + 1 <= tout[v]) {
                    update(1, 1, N, tin[v] + 1, tout[v], v);
                }
            }
        }
    }

    return 0;
}
